  @protected
  void sse_encode_block(Block self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case Block_Text(inlines: final inlines):
        sse_encode_i_32(0, serializer);
        sse_encode_list_inline(inlines, serializer);
      case Block_Image(url: final url, alt: final alt):
        sse_encode_i_32(1, serializer);
        sse_encode_String(url, serializer);
        sse_encode_String(alt, serializer);
      case Block_Table(rows: final rows, hasHeaderRow: final hasHeaderRow):
        sse_encode_i_32(2, serializer);
        sse_encode_list_list_list_inline(rows, serializer);
        sse_encode_bool(hasHeaderRow, serializer);
      case Block_Attachment(name: final name, url: final url):
        sse_encode_i_32(3, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(url, serializer);
    }
  }

